// Package agent owns one local Nginx deployment and its durable binding gate.
// Public binding delivery cannot invoke deployment operations.
package agent

import (
	"bytes"
	"crypto/x509"
	"encoding/json"
	"fmt"
	"io"
	"net"
	"net/url"
	"os"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"time"

	"github.com/cztamas/qwacamole/credentials"
	"github.com/cztamas/qwacamole/store"
)

// Config is a single-host, local Nginx deployment. Paths are absolute. The
// configured Nginx file is generated by RenderNginx; arbitrary includes and
// certificate managers are intentionally unsupported.
type Config struct {
	Version              int           `json:"config_version,omitempty"`
	Serving              ServingConfig `json:"serving,omitempty"`
	Host                 string        `json:"hostname"`
	RuntimeDir           string        `json:"runtime_directory,omitempty"`
	StateDir             string        `json:"state_directory"`
	ChainFiles           []string      `json:"qwac_chain_files"`
	KeyFile              string        `json:"qwac_key_file"`
	TrustFile            string        `json:"qwac_trust_file"`
	TLSRoots             string        `json:"tls_roots,omitempty"`
	CertbotLineage       string        `json:"certbot_lineage"`
	PublicListen         string        `json:"binding_listen"`
	HTTPListen           string        `json:"http_listen"`
	HTTPSListen          string        `json:"https_listen"`
	ProbeAddress         string        `json:"probe_address"`
	Application          string        `json:"application"`
	Webroot              string        `json:"challenge_webroot"`
	NginxBinary          string        `json:"nginx_binary"`
	NginxPrefix          string        `json:"nginx_prefix"`
	NginxConfig          string        `json:"nginx_config"`
	Lifetime             string        `json:"binding_lifetime,omitempty"`
	RefreshBefore        string        `json:"refresh_before,omitempty"`
	DocumentGrace        string        `json:"document_grace,omitempty"`
	MaxCertificates      int           `json:"max_certificates,omitempty"`
	MaxDocumentBytes     int64         `json:"max_document_bytes,omitempty"`
	FirefoxCompatibility bool          `json:"firefox_compatibility,omitempty"`
}

// LoadConfig rejects unknown fields and unsupported configurations.
func LoadConfig(path string) (Config, error) {
	var c Config
	d, e := os.ReadFile(path)
	if e != nil {
		return c, e
	}
	dec := json.NewDecoder(bytes.NewReader(d))
	dec.DisallowUnknownFields()
	if e = dec.Decode(&c); e != nil {
		return c, e
	}
	if e = dec.Decode(new(any)); e != io.EOF {
		return c, fmt.Errorf("one JSON config required")
	}
	return c, c.Validate()
}
func validHost(host string) bool {
	if len(host) > 253 || host == "" {
		return false
	}
	label := regexp.MustCompile(`^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$`)
	for _, s := range strings.Split(host, ".") {
		if !label.MatchString(s) {
			return false
		}
	}
	return net.ParseIP(host) == nil
}
func (c Config) Validate() error {
	if c.Version != 0 && c.Version != 1 {
		return fmt.Errorf("unsupported config_version %d; use a compatible agent", c.Version)
	}
	if _, e := c.Serving.values(); e != nil {
		return e
	}
	if !filepath.IsAbs(c.runtimeDir()) || len(c.Socket()) > 100 {
		return fmt.Errorf("control socket needs an absolute private runtime_directory with socket path at most 100 bytes")
	}
	if !validHost(c.Host) {
		return fmt.Errorf("one literal lowercase DNS hostname required")
	}

	for _, p := range append([]string{c.StateDir, c.KeyFile, c.TrustFile, c.CertbotLineage, c.Webroot, c.NginxBinary, c.NginxPrefix, c.NginxConfig}, c.ChainFiles...) {
		if !filepath.IsAbs(p) || strings.ContainsAny(p, "\"\r\n;$*?[]{}") {
			return fmt.Errorf("absolute safe configuration path required: %q", p)
		}
	}
	if len(c.ChainFiles) == 0 {
		return fmt.Errorf("QWAC chain files required")
	}
	for _, addr := range []string{c.PublicListen, c.HTTPListen, c.HTTPSListen, c.ProbeAddress} {
		h, p, e := net.SplitHostPort(addr)
		port, portErr := strconv.Atoi(p)
		if e != nil || net.ParseIP(h) == nil || portErr != nil || port < 1 || port > 65535 {
			return fmt.Errorf("literal IP:port required: %q", addr)
		}
	}
	h, _, _ := net.SplitHostPort(c.PublicListen)
	if !net.ParseIP(h).IsLoopback() {
		return fmt.Errorf("binding service must listen on loopback")
	}
	h, _, _ = net.SplitHostPort(c.ProbeAddress)
	if !net.ParseIP(h).IsLoopback() {
		return fmt.Errorf("deployment confirmation must target local Nginx")
	}
	u, e := url.Parse(c.Application)
	if e != nil || u.Scheme != "http" || u.Host == "" || u.User != nil || u.RawQuery != "" || u.Fragment != "" || u.Path != "" || strings.ContainsAny(c.Application, "\"\r\n;$ ") {
		return fmt.Errorf("one HTTP reverse-proxy application origin required")
	}
	if !validHost(u.Hostname()) && net.ParseIP(u.Hostname()) == nil {
		return fmt.Errorf("application must use a literal hostname or IP origin")
	}
	if c.TLSRoots != "" && !filepath.IsAbs(c.TLSRoots) {
		return fmt.Errorf("TLS roots path must be absolute")
	}
	_, e = c.StoreConfig()
	return e
}
func (c Config) StoreConfig() (store.Config, error) {
	s := store.Config{Dir: filepath.Join(c.StateDir, "bindings"), Host: c.Host, MaxCertificates: c.MaxCertificates, MaxDocumentBytes: c.MaxDocumentBytes, FirefoxCompatibility: c.FirefoxCompatibility}
	for _, setting := range []struct {
		text string
		dst  *time.Duration
	}{{c.Lifetime, &s.Lifetime}, {c.RefreshBefore, &s.RefreshBefore}, {c.DocumentGrace, &s.DocumentGrace}} {
		text, dst := setting.text, setting.dst
		if text != "" {
			d, e := time.ParseDuration(text)
			if e != nil {
				return s, e
			}
			*dst = d
		}
	}
	return s.WithDefaults()
}
func (c Config) Material() (*credentials.Credentials, error) {
	m, e := credentials.Load(c.ChainFiles, c.KeyFile)
	if e != nil {
		return nil, e
	}
	root, e := credentials.ReadCert(c.TrustFile)
	if e != nil {
		return nil, e
	}
	return m, m.ValidateFor(c.Host, root, time.Now())
}
func (c Config) roots() (*x509.CertPool, error) {
	if c.TLSRoots == "" {
		return nil, nil
	}
	d, e := os.ReadFile(c.TLSRoots)
	if e != nil {
		return nil, e
	}
	roots := x509.NewCertPool()
	if !roots.AppendCertsFromPEM(d) {
		return nil, fmt.Errorf("invalid TLS roots")
	}
	return roots, nil
}
func (c Config) runtimeDir() string {
	if c.RuntimeDir != "" {
		return c.RuntimeDir
	}
	return c.StateDir
}
func (c Config) Socket() string { return filepath.Join(c.runtimeDir(), "control.sock") }
